MODES = {}
for s,n,c,i,d,ex,be,re,fo,li,pr in M:
    MODES[s] = dict(slug=s,name=n,category=c,icon=i,description=d,suggested_prompts=pr,
      system_prompt=BASE+f"MODE: {n}\nIdentity: a specialist in {ex}.\nBehavior: {be}.\nReasoning: {re}.\nFormat: {fo}.\nLimits: {li}.")
def public_modes(): return [{k:v for k,v in m.items() if k!="system_prompt"} for m in MODES.values()]
